// topic = smartfarm/{farmId}/config/update
var parts = msg.topic.split('/');
var farmId = parts[1] || global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';

msg.url = 'https://api.smartgreen.kr/api/config/' + farmId;
msg.method = 'GET';
msg.headers = {
    'x-api-key': global.get('SENSOR_API_KEY') || 'smartfarm-sensor-key',
    'Accept': 'application/json'
};
msg._farmId = farmId;
return msg;

// 백엔드 응답 → houseConfig global 갱신
if (!msg.payload || !msg.payload.success) {
    node.warn('❌ houseConfig 갱신 실패: ' + JSON.stringify(msg.payload).slice(0, 200));
    node.status({ fill: 'red', shape: 'ring', text: 'fetch fail' });
    return null;
}

var data = msg.payload.data;
if (!data || !Array.isArray(data.houses)) {
    node.warn('❌ houseConfig 형식 오류');
    return null;
}

var prev = global.get('houseConfig') || {};
var prevHouseCount = (prev.houses || []).length;
var prevDeviceCount = (prev.houses || []).reduce(function (s, h) { return s + (h.devices || []).length; }, 0);

global.set('houseConfig', data);

var newHouseCount = data.houses.length;
var newDeviceCount = data.houses.reduce(function (s, h) { return s + (h.devices || []).length; }, 0);

node.warn('✅ houseConfig 갱신: ' + newHouseCount + '개 하우스, ' + newDeviceCount + '개 디바이스 (이전 ' + prevHouseCount + '/' + prevDeviceCount + ')');
node.status({ fill: 'green', shape: 'dot', text: newDeviceCount + 'devs ' + new Date().toLocaleTimeString() });

// 워치독 모듈 캐시 무효화 (다음 폴링에 재계산)
global.set('_watchdogModules', null);

msg.payload = {
    success: true,
    farmId: msg._farmId,
    houses: newHouseCount,
    devices: newDeviceCount,
    timestamp: new Date().toISOString()
};
return msg;
